/**
 * Look up parameter metadata by library and LVO offset.
 */
export function getLvoParams(library: string, offset: number): LvoParam[] | undefined {
  const map = ALL_LVO_PARAMS[library.toLowerCase()];
  return map ? map[offset] : undefined;
}
